script:
(function () {
  'use strict';
  // Savings goal: monthly compounding at (annual return / 12), deposits at the end of each month
  // (or the start, under More options).
  //   Monthly deposit needed = (goal - saved x (1+i)^n) / (((1+i)^n - 1) / i x (1+i if start of month))
  //   With 0% return: (goal - saved) / n.  Inflation option: goal is in today's dollars and grows
  //   by (1 + inflation)^(years) - for the time mode the target grows month by month.
  //   Time to goal: month-by-month simulation (capped at 100 years).
  // Verified (Node scratch test): $20,000 goal, $2,000 saved, 4%, 5 years -> $264.83/month at month
  // end, $263.95 at month start (closed-form annuity, checked in Python). Textbook: $100/month at
  // 6% for 10 years grows to $16,387.93, and the calculator returns exactly $100.00 for that goal.
  // Time mode: $300/month -> 54 months (NPER formula gives 53.7, rounded up to a whole month).
  // 0% return: ($20,000 - $2,000) / 60 = $300.00. 3% inflation: goal becomes $23,185 in 5 years.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var MAX_MONTHS = 1200;

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function monthlyNeeded(goal, saved, i, n, begin) {
    var grow = Math.pow(1 + i, n);
    var need = goal - saved * grow;
    if (need <= 0) return 0;
    var factor = i === 0 ? n : (grow - 1) / i * (begin ? 1 + i : 1);
    return need / factor;
  }

  function step(bal, i, pmt, begin) {
    return begin ? (bal + pmt) * (1 + i) : bal * (1 + i) + pmt;
  }

  // Months until the balance reaches the (possibly inflating) goal; -1 if not within MAX_MONTHS.
  function monthsToGoal(goal, saved, i, pmt, begin, infl) {
    if (saved >= goal) return 0;
    var bal = saved;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      bal = step(bal, i, pmt, begin);
      if (bal >= goal * Math.pow(1 + infl, m / 12) - 1e-9) return m;
    }
    return -1;
  }

  function schedule(saved, i, pmt, begin, months) {
    var rows = [], bal = saved, contributed = saved;
    for (var m = 1; m <= months; m++) {
      bal = step(bal, i, pmt, begin);
      contributed += pmt;
      if (m % 12 === 0 || m === months) {
        rows.push({ label: m % 12 === 0 ? String(m / 12) : (Math.floor(m / 12) + ' yr ' + (m % 12) + ' mo'),
                    contributed: contributed, balance: bal });
      }
    }
    return { rows: rows, balance: bal, contributed: contributed };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function cell(tr, text) {
    var td = document.createElement('td');
    td.textContent = text;
    tr.appendChild(td);
  }

  function update() {
    var mode = document.getElementById('sgMode').value;
    var begin = document.getElementById('sgTiming').value === 'start';
    var goal = num('sgGoal'), saved = num('sgSaved'), rate = num('sgRate'), years = num('sgYears'),
        pmt = num('sgMonthly'), infl = num('sgInflation');
    document.getElementById('sgYearsWrap').hidden = mode !== 'payment';
    document.getElementById('sgMonthlyWrap').hidden = mode !== 'time';
    var error = document.getElementById('sgError');
    var bad = [goal, saved, rate, infl].some(isNaN) || goal <= 0 || saved < 0 || rate < 0 || rate > 50 ||
      infl < 0 || infl > 20 ||
      (mode === 'payment' && (isNaN(years) || years <= 0 || years > 100)) ||
      (mode === 'time' && (isNaN(pmt) || pmt < 0));
    error.hidden = !bad;
    if (bad) {
      error.textContent = mode === 'payment'
        ? 'Enter a goal above $0, non-negative savings, a return from 0 to 50%, inflation up to 20% and 1 month to 100 years.'
        : 'Enter a goal above $0, non-negative savings and monthly deposit, a return from 0 to 50% and inflation up to 20%.';
      return;
    }
    var i = rate / 1200, inflation = infl / 100, months, deposit, target;
    var note = document.getElementById('sgNote');
    if (mode === 'payment') {
      months = Math.max(1, Math.round(years * 12));
      target = goal * Math.pow(1 + inflation, months / 12);
      deposit = monthlyNeeded(target, saved, i, months, begin);
      set('sgMainLabel', 'Monthly savings needed');
      set('sgMain', money.format(deposit));
      note.textContent = deposit === 0
        ? 'Your current savings reach the goal on their own at this return.'
        : 'Saving ' + money.format(deposit) + ' a month for ' + duration(months) + ' reaches the goal.';
    } else {
      deposit = pmt;
      months = monthsToGoal(goal, saved, i, pmt, begin, inflation);
      set('sgMainLabel', 'Time to reach your goal');
      if (months < 0) {
        set('sgMain', 'Over 100 years');
        note.textContent = 'At this deposit and return the goal is not reached within 100 years. Try a larger deposit.';
        months = MAX_MONTHS;
      } else {
        set('sgMain', months === 0 ? 'Reached now' : duration(months));
        note.textContent = months === 0 ? 'Your current savings already cover the goal.'
          : 'Based on ' + money.format(pmt) + ' a month.';
      }
      target = goal * Math.pow(1 + inflation, months / 12);
    }
    var s = schedule(saved, i, deposit, begin, months);
    set('sgContributed', money0.format(s.contributed));
    set('sgInterest', money0.format(Math.max(0, s.balance - s.contributed)));
    set('sgFinal', money0.format(s.balance));
    set('sgTarget', money0.format(target));
    document.getElementById('sgTargetRow').hidden = inflation === 0;

    var body = document.getElementById('sgSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    s.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      cell(tr, row.label);
      cell(tr, money0.format(row.contributed));
      cell(tr, money0.format(row.balance - row.contributed));
      cell(tr, money0.format(row.balance));
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sgForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
